-- SOLO LECTURA. HUELLA ÚNICA para comparar ANTES y DESPUÉS de la baja de #602 (y de la eliminación de #603, si se aprueba).
-- Es UNA sentencia que devuelve UNA fila. Se ejecuta dos veces (antes y después) y se comparan las dos filas con el runbook.
--   * `huella_inmutable`  debe ser IDÉNTICA antes y después: resume FONDO-000135 y sus líneas, las líneas de fondo/compras/unidades/planes de #1296 y #1297,
--     los filtros y accesos de #602, las claves foráneas hacia flota_vehiculos, el total de fichas por empresa y las filas completas de #603, #1296 y #1297 y de #602
--     EXCLUYENDO sus columnas de estado (activo, estado, en_taller, fecha_entrada_taller, motivo_taller).
--   * `estado_fichas`     es lo ÚNICO que debe cambiar con la baja de #602: «602:1/Activo» pasa a «602:0/Inactivo».
-- Sin INSERT/UPDATE/DELETE/DDL/CALL/PREPARE/SET. Es una consulta administrativa (ve todas las empresas): no compartir resultados fuera del equipo responsable.

SELECT
  x.h1_solicitud, x.h1_lineas_fondo, x.h3_602_filtros_accesos_lineas, x.h4_1296, x.h4_1297, x.h5_claves_foraneas, x.h5_fichas_por_empresa,
  x.fila_603, x.fila_1296, x.fila_1297, x.fila_602_sin_estado, x.estado_fichas,
  MD5(CONCAT_WS('#', x.h1_solicitud, x.h1_lineas_fondo, x.h3_602_filtros_accesos_lineas, x.h4_1296, x.h4_1297, x.h5_claves_foraneas, x.h5_fichas_por_empresa,
                x.fila_603, x.fila_1296, x.fila_1297, x.fila_602_sin_estado)) AS huella_inmutable
FROM (SELECT
  -- H1: la solicitud FONDO-000135 y sus líneas (histórica, Liquidada): no debe cambiar nunca.
  (SELECT MD5(CONCAT_WS('|', s.id, s.codigo, s.estado, s.total, IFNULL(s.autorizado_en, ''), IFNULL(s.liquidado_en, ''))) FROM tms_solicitudes_fondo s WHERE s.codigo = 'FONDO-000135') AS h1_solicitud,
  (SELECT MD5(GROUP_CONCAT(CONCAT_WS('|', l.id, l.vehiculo_id, l.placa, l.categoria, l.cantidad, l.monto, IFNULL(l.fecha_viaje, ''), IFNULL(l.empleado_id, ''), IFNULL(l.plan_id, '')) ORDER BY l.id SEPARATOR ';'))
     FROM tms_solicitud_fondo_lineas l JOIN tms_solicitudes_fondo s ON s.empresa_id = l.empresa_id AND s.id = l.solicitud_id WHERE s.codigo = 'FONDO-000135') AS h1_lineas_fondo,
  -- H3: lo que debe permanecer de #602 (filtros / accesos / líneas de fondo).
  CONCAT_WS('/', (SELECT COUNT(*) FROM flota_vehiculo_filtros WHERE vehiculo_id = 602), (SELECT COUNT(*) FROM flota_vehiculo_acceso WHERE vehiculo_id = 602), (SELECT COUNT(*) FROM tms_solicitud_fondo_lineas WHERE vehiculo_id = 602)) AS h3_602_filtros_accesos_lineas,
  -- H4: fichas correctas (líneas de fondo / suma / compras / unidad TMS / planes).
  CONCAT_WS('/', (SELECT COUNT(*) FROM tms_solicitud_fondo_lineas WHERE vehiculo_id = 1296), (SELECT IFNULL(SUM(monto), 0) FROM tms_solicitud_fondo_lineas WHERE vehiculo_id = 1296), (SELECT COUNT(*) FROM compras_requerimiento_lineas WHERE vehiculo_id = 1296),
     IFNULL((SELECT GROUP_CONCAT(u.id) FROM tms_unidades u WHERE u.flota_vehiculo_id = 1296), '-'), (SELECT COUNT(*) FROM tms_planes_viaje p JOIN tms_unidades u ON u.id = p.unidad_id WHERE u.flota_vehiculo_id = 1296)) AS h4_1296,
  CONCAT_WS('/', (SELECT COUNT(*) FROM tms_solicitud_fondo_lineas WHERE vehiculo_id = 1297), (SELECT IFNULL(SUM(monto), 0) FROM tms_solicitud_fondo_lineas WHERE vehiculo_id = 1297), (SELECT COUNT(*) FROM compras_requerimiento_lineas WHERE vehiculo_id = 1297),
     IFNULL((SELECT GROUP_CONCAT(u.id) FROM tms_unidades u WHERE u.flota_vehiculo_id = 1297), '-'), (SELECT COUNT(*) FROM tms_planes_viaje p JOIN tms_unidades u ON u.id = p.unidad_id WHERE u.flota_vehiculo_id = 1297)) AS h4_1297,
  -- H5: claves foráneas hacia flota_vehiculos y número de fichas por empresa (el total no cambia con una baja).
  (SELECT COUNT(*) FROM information_schema.KEY_COLUMN_USAGE WHERE TABLE_SCHEMA = DATABASE() AND REFERENCED_TABLE_NAME = 'flota_vehiculos') AS h5_claves_foraneas,
  (SELECT GROUP_CONCAT(CONCAT(t.empresa_id, ':', t.fichas) ORDER BY t.empresa_id SEPARATOR ';') FROM (SELECT empresa_id, COUNT(*) AS fichas FROM flota_vehiculos GROUP BY empresa_id) t) AS h5_fichas_por_empresa,
  -- Filas completas (todas las columnas de la ficha). #602 se resume SIN sus columnas de estado, que son lo único que la baja modifica.
  (SELECT MD5(CONCAT_WS('|', v.id, v.empresa_id, v.placa, IFNULL(v.marca,''), IFNULL(v.modelo,''), IFNULL(v.descripcion,''), IFNULL(v.tipo_unidad,''), IFNULL(v.color,''), IFNULL(v.tipo_combustible,''), IFNULL(v.chasis,''), IFNULL(v.capacidad,''), IFNULL(v.credito,''), IFNULL(v.empresa_activo,''), IFNULL(v.nit,''), IFNULL(v.condicion_propiedad,''), IFNULL(v.seguros,''), IFNULL(v.km_actual,''), IFNULL(v.km_intervalo_servicio,''), IFNULL(v.km_ultimo_servicio,''), IFNULL(v.fecha_ultimo_servicio,''), IFNULL(v.odometro_funcional,''), IFNULL(v.mantenimiento_intervalo_meses,''), v.en_taller, IFNULL(v.fecha_entrada_taller,''), IFNULL(v.motivo_taller,''), v.estado, v.activo, IFNULL(v.notas,''), IFNULL(v.filtro_servicio_mayor,''), IFNULL(v.filtro_servicio_menor,''), IFNULL(v.rin_llanta,''), IFNULL(v.medida_llanta,''), IFNULL(v.tipo_aceite,''), IFNULL(v.tipo_propiedad,''), IFNULL(v.empresa_propietaria_id,''), IFNULL(v.propietario_externo,''), IFNULL(v.tipo_vehiculo,''), IFNULL(v.revision_propiedad,''))) FROM flota_vehiculos v WHERE v.id = 603) AS fila_603,
  (SELECT MD5(CONCAT_WS('|', v.id, v.empresa_id, v.placa, IFNULL(v.marca,''), IFNULL(v.modelo,''), IFNULL(v.descripcion,''), IFNULL(v.tipo_unidad,''), IFNULL(v.color,''), IFNULL(v.tipo_combustible,''), IFNULL(v.chasis,''), IFNULL(v.capacidad,''), IFNULL(v.credito,''), IFNULL(v.empresa_activo,''), IFNULL(v.nit,''), IFNULL(v.condicion_propiedad,''), IFNULL(v.seguros,''), IFNULL(v.km_actual,''), IFNULL(v.km_intervalo_servicio,''), IFNULL(v.km_ultimo_servicio,''), IFNULL(v.fecha_ultimo_servicio,''), IFNULL(v.odometro_funcional,''), IFNULL(v.mantenimiento_intervalo_meses,''), v.en_taller, IFNULL(v.fecha_entrada_taller,''), IFNULL(v.motivo_taller,''), v.estado, v.activo, IFNULL(v.notas,''), IFNULL(v.filtro_servicio_mayor,''), IFNULL(v.filtro_servicio_menor,''), IFNULL(v.rin_llanta,''), IFNULL(v.medida_llanta,''), IFNULL(v.tipo_aceite,''), IFNULL(v.tipo_propiedad,''), IFNULL(v.empresa_propietaria_id,''), IFNULL(v.propietario_externo,''), IFNULL(v.tipo_vehiculo,''), IFNULL(v.revision_propiedad,''))) FROM flota_vehiculos v WHERE v.id = 1296) AS fila_1296,
  (SELECT MD5(CONCAT_WS('|', v.id, v.empresa_id, v.placa, IFNULL(v.marca,''), IFNULL(v.modelo,''), IFNULL(v.descripcion,''), IFNULL(v.tipo_unidad,''), IFNULL(v.color,''), IFNULL(v.tipo_combustible,''), IFNULL(v.chasis,''), IFNULL(v.capacidad,''), IFNULL(v.credito,''), IFNULL(v.empresa_activo,''), IFNULL(v.nit,''), IFNULL(v.condicion_propiedad,''), IFNULL(v.seguros,''), IFNULL(v.km_actual,''), IFNULL(v.km_intervalo_servicio,''), IFNULL(v.km_ultimo_servicio,''), IFNULL(v.fecha_ultimo_servicio,''), IFNULL(v.odometro_funcional,''), IFNULL(v.mantenimiento_intervalo_meses,''), v.en_taller, IFNULL(v.fecha_entrada_taller,''), IFNULL(v.motivo_taller,''), v.estado, v.activo, IFNULL(v.notas,''), IFNULL(v.filtro_servicio_mayor,''), IFNULL(v.filtro_servicio_menor,''), IFNULL(v.rin_llanta,''), IFNULL(v.medida_llanta,''), IFNULL(v.tipo_aceite,''), IFNULL(v.tipo_propiedad,''), IFNULL(v.empresa_propietaria_id,''), IFNULL(v.propietario_externo,''), IFNULL(v.tipo_vehiculo,''), IFNULL(v.revision_propiedad,''))) FROM flota_vehiculos v WHERE v.id = 1297) AS fila_1297,
  (SELECT MD5(CONCAT_WS('|', v.id, v.empresa_id, v.placa, IFNULL(v.marca,''), IFNULL(v.modelo,''), IFNULL(v.descripcion,''), IFNULL(v.tipo_unidad,''), IFNULL(v.color,''), IFNULL(v.tipo_combustible,''), IFNULL(v.chasis,''), IFNULL(v.capacidad,''), IFNULL(v.credito,''), IFNULL(v.empresa_activo,''), IFNULL(v.nit,''), IFNULL(v.condicion_propiedad,''), IFNULL(v.seguros,''), IFNULL(v.km_actual,''), IFNULL(v.km_intervalo_servicio,''), IFNULL(v.km_ultimo_servicio,''), IFNULL(v.fecha_ultimo_servicio,''), IFNULL(v.odometro_funcional,''), IFNULL(v.mantenimiento_intervalo_meses,''), IFNULL(v.notas,''), IFNULL(v.filtro_servicio_mayor,''), IFNULL(v.filtro_servicio_menor,''), IFNULL(v.rin_llanta,''), IFNULL(v.medida_llanta,''), IFNULL(v.tipo_aceite,''), IFNULL(v.tipo_propiedad,''), IFNULL(v.empresa_propietaria_id,''), IFNULL(v.propietario_externo,''), IFNULL(v.tipo_vehiculo,''), IFNULL(v.revision_propiedad,''))) FROM flota_vehiculos v WHERE v.id = 602) AS fila_602_sin_estado,
  -- Estado visible (esto SÍ cambia con la baja de #602).
  (SELECT GROUP_CONCAT(CONCAT(v.id, ':', v.activo, '/', v.estado) ORDER BY v.id SEPARATOR ';') FROM flota_vehiculos v WHERE v.id IN (602, 603, 1296, 1297)) AS estado_fichas
) x;
